namespace CloudServer;
public sealed class UserAccount { public string Id {get;set;}=Guid.NewGuid().ToString("N"); public string UserName {get;set;}=""; public string DisplayName {get;set;}=""; public string PasswordHash {get;set;}=""; public bool IsAdmin {get;set;} public long QuotaBytes {get;set;}=0; public List<string> GroupIds {get;set;}=new(); }
